import 'package:flutter/material.dart'; import '../core/theme.dart';
class StatCard extends StatelessWidget {const StatCard({super.key,required this.title,required this.value,this.icon=Icons.analytics_outlined});final String title,value;final IconData icon;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(15),border:Border.all(color:const Color(0xFFE0E5E8))),child:Row(children:[Container(width:42,height:42,decoration:BoxDecoration(color:MTheme.ink,borderRadius:BorderRadius.circular(12)),child:Icon(icon,color:MTheme.lime)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(title,style:const TextStyle(fontSize:12,color:MTheme.muted))]))]));}
void snack(BuildContext c,String m,{bool error=false})=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(m),backgroundColor:error?Colors.red.shade700:MTheme.ink));
Future<DateTime?> pickDate(BuildContext c,DateTime initial)=>showDatePicker(context:c,firstDate:DateTime(2000),lastDate:DateTime(2100),initialDate:initial);
String money(dynamic v)=>'₺${(double.tryParse('$v')??0).toStringAsFixed(2)}';
